import numpy as np
from scipy.special import gammaln

def q(l,n):
    if l<2:return 0.
    return ((l-1)*(l+n-1))**2*np.exp(gammaln((l-1)/2)+gammaln((l+n)/2)-np.log(2)-gammaln(l/2)-gammaln((l+n+1)/2))
for n in range(3,51):
    m=n-1
    vals=[]
    for l in range(2,101):
        A=(l-1)**2*(l+m-1)/(2*l+m-1)
        B=(l+m)**2*l/(2*l+m-1)
        d=-l*(l+m-1)+m+1
        vals.append(d+A*q(l+1,n)/q(l,n)+B*q(l-1,n)/q(l,n))
    if min(vals)<0 or n in [3,4,5,6,7,8,24,25]:
        print(n, min(vals), 'degree',np.argmin(vals)+2)

